import java.util.*;

class Solution {
  static final long MOD = 1_000_000_007L;

  public int maximumScore(List<Integer> nums, int k) {
    int n = nums.size(), max = 0;
    for (int v : nums) max = Math.max(max, v);
    int[] spf = new int[max + 1];
    for (int i = 2; i <= max; i++)
      if (spf[i] == 0) for (int j = i; j <= max; j += i) if (spf[j] == 0) spf[j] = i;
    int[] score = new int[n];
    for (int i = 0; i < n; i++) {
      int v = nums.get(i), count = 0;
      while (v > 1) {
        int p = spf[v];
        count++;
        while (v % p == 0) v /= p;
      }
      score[i] = count;
    }
    long[] left = new long[n], right = new long[n];
    ArrayDeque<Integer> st = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
      while (!st.isEmpty() && score[st.peek()] < score[i]) st.pop();
      left[i] = st.isEmpty() ? i + 1L : i - st.peek();
      st.push(i);
    }
    st.clear();
    for (int i = n - 1; i >= 0; i--) {
      while (!st.isEmpty() && score[st.peek()] <= score[i]) st.pop();
      right[i] = st.isEmpty() ? n - i : st.peek() - i;
      st.push(i);
    }
    Integer[] order = new Integer[n];
    for (int i = 0; i < n; i++) order[i] = i;
    Arrays.sort(order, (i, j) -> Integer.compare(nums.get(j), nums.get(i)));
    long ans = 1;
    long remaining = k;
    for (int i : order) {
      long take = Math.min(remaining, left[i] * right[i]);
      ans = ans * modPow(nums.get(i), take) % MOD;
      remaining -= take;
      if (remaining == 0) break;
    }
    return (int) ans;
  }

  private long modPow(long a, long e) {
    long r = 1;
    while (e > 0) {
      if ((e & 1) != 0) r = r * a % MOD;
      a = a * a % MOD;
      e >>= 1;
    }
    return r;
  }
}
